(function() {
  'use strict';

  // Teaching Assumptions
  const Q = 0.3; // Probability of '1' in Bernoulli source
  const EPSILON = 0.1; // Tolerance for typicality

  // DOM Elements
  const inputN = document.getElementById('input-n');
  const valN = document.getElementById('val-n');
  const btnReset = document.getElementById('btn-reset');
  const canvas = document.getElementById('typical-chart');
  const ctx = canvas.getContext('2d');

  // Stats Elements with data-value for verification
  const statTotal = document.getElementById('stat-total');
  const statTypical = document.getElementById('stat-typical');
  const statProb = document.getElementById('stat-prob');
  const statEntropy = document.getElementById('stat-entropy');

  // State
  let currentN = parseInt(inputN.value, 10);

  // Helper: Log2
  function log2(x) {
    return Math.log(x) / Math.log(2);
  }

  // Helper: Factorial with caching for small N
  const factCache = [1];
  function factorial(n) {
    if (factCache[n]) return factCache[n];
    let res = 1;
    for (let i = 2; i <= n; i++) res *= i;
    factCache[n] = res;
    return res;
  }

  // Helper: Binomial Coefficient
  function binom(n, k) {
    if (k < 0 || k > n) return 0;
    return factorial(n) / (factorial(k) * factorial(n - k));
  }

  // Core Calculation
  function calculateStats(n) {
    // Entropy H(q)
    const h = -(Q * log2(Q) + (1 - Q) * log2(1 - Q));

    let typicalCount = 0;
    let typicalProb = 0;
    const totalSequences = Math.pow(2, n);

    // Bounds for typical k (number of 1s)
    // Condition: | -1/N * log P(x) - H | <= epsilon
    // -1/N * (k*log q + (n-k)*log(1-q)) approx H
    // k/N approx q
    // Range: n(q - eps) to n(q + eps)
    const kMin = Math.max(0, Math.ceil(n * (Q - EPSILON / Math.abs(log2((1-Q)/Q))) - 1e-12));
    const kMax = Math.min(n, Math.floor(n * (Q + EPSILON / Math.abs(log2((1-Q)/Q))) + 1e-12));

    // Calculate exact sums
    for (let k = 0; k <= n; k++) {
      const probK = binom(n, k) * Math.pow(Q, k) * Math.pow(1 - Q, n - k);

      if (k >= kMin && k <= kMax) {
        typicalCount += binom(n, k);
        typicalProb += probK;
      }
    }

    return {
      total: totalSequences,
      typical: typicalCount,
      prob: typicalProb,
      entropy: h,
      kMin: kMin,
      kMax: kMax
    };
  }

  // Drawing Logic
  function drawChart(stats) {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 50;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // Find max probability for scaling Y axis
    let maxProb = 0;
    const barData = [];
    for (let k = 0; k <= currentN; k++) {
      const p = binom(currentN, k) * Math.pow(Q, k) * Math.pow(1 - Q, currentN - k);
      barData.push({k, p});
      if (p > maxProb) maxProb = p;
    }

    // Draw Axes
    ctx.beginPath();
    ctx.strokeStyle = '#1a2b4a';
    ctx.lineWidth = 2;
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // Labels
    ctx.fillStyle = '#1a2b4a';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Number of 1s (k)', canvas.width / 2, canvas.height - 15);

    ctx.save();
    ctx.translate(15, canvas.height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center';
    ctx.fillText('Probability Mass', 0, 0);
    ctx.restore();

    // Draw Bars
    const barWidth = Math.max(2, chartWidth / (currentN + 1) - 2);

    barData.forEach((item, index) => {
      const x = padding + index * (chartWidth / (currentN + 1)) + (chartWidth / (currentN + 1) - barWidth) / 2;
      const h = (item.p / maxProb) * chartHeight;
      const y = canvas.height - padding - h;

      // Check if typical
      const isTypical = item.k >= stats.kMin && item.k <= stats.kMax;

      ctx.fillStyle = isTypical ? '#007acc' : '#d1c7b7'; // Accent for typical, Muted for non-typical
      ctx.fillRect(x, y, barWidth, h);

      // Draw k label only if space allows or at ends
      if (currentN <= 20 || index === 0 || index === currentN || isTypical) {
         ctx.fillStyle = '#5c6b7f';
         ctx.font = '10px sans-serif';
         if (currentN > 30 && !isTypical) {
             // Sparse labels for large N
             if (index % 5 !== 0) return;
         }
         ctx.fillText(item.k, x + barWidth/2, canvas.height - padding + 12);
      }
    });

    // Annotation
    ctx.fillStyle = '#b85c38';
    ctx.font = 'italic 12px serif';
    ctx.textAlign = 'right';
    ctx.fillText(`Typical Region: [${stats.kMin}, ${stats.kMax}]`, canvas.width - padding, padding + 20);
  }

  // Update UI
  function update() {
    currentN = parseInt(inputN.value, 10);
    valN.textContent = currentN;

    const stats = calculateStats(currentN);

    // Update Text and Data Attributes for Verification
    statTotal.textContent = stats.total.toLocaleString();
    statTotal.setAttribute('data-value', stats.total);

    statTypical.textContent = stats.typical.toLocaleString();
    statTypical.setAttribute('data-value', stats.typical);

    statProb.textContent = stats.prob.toFixed(6);
    statProb.setAttribute('data-value', stats.prob);

    statEntropy.textContent = stats.entropy.toFixed(4);
    statEntropy.setAttribute('data-value', stats.entropy);

    drawChart(stats);
  }

  // Event Listeners
  inputN.addEventListener('input', update);

  btnReset.addEventListener('click', function() {
    inputN.value = 10;
    update();
  });

  // Handle reduced motion
  const query = window.matchMedia('(prefers-reduced-motion: reduce)');
  if (query.matches) {
    // Static draw only
  }

  // Initial Draw
  update();

})();
